const sumOutActivityByAssetSince = `-- name: SumOutActivityByAssetSince :one
SELECT COALESCE(SUM(amount_minor), 0)::bigint FROM stablecoin_activity
WHERE wallet_id = $1
  AND direction = 'out'
  AND asset = $2
  AND status != 'failed'
  AND occurred_at >= $3
`

type SumOutActivityByAssetSinceParams struct {
	WalletID pgtype.UUID        `json:"wallet_id"`
	Asset    string             `json:"asset"`
	Since    pgtype.Timestamptz `json:"since"`
}

// Delegated-signer daily-cap check — confirmed+pending out-volume for one
// asset since a cutoff (pending counts: racing parallel ops must see the
// cap too).
func (q *Queries) SumOutActivityByAssetSince(ctx context.Context, arg SumOutActivityByAssetSinceParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumOutActivityByAssetSince, arg.WalletID, arg.Asset, arg.Since)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const upsertTreasuryWallet = `-- name: UpsertTreasuryWallet :one

INSERT INTO treasury_wallets (role, chain, address, locator, float_cap_minor)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (chain, role) DO UPDATE SET
    address = EXCLUDED.address,
    locator = EXCLUDED.locator,
    float_cap_minor = EXCLUDED.float_cap_minor
RETURNING id, role, chain, address, locator, float_cap_minor, created_at
`

type UpsertTreasuryWalletParams struct {
	Role          string  `json:"role"`
	Chain         string  `json:"chain"`
	Address       string  `json:"address"`
	Locator       *string `json:"locator"`
	FloatCapMinor *int64  `json:"float_cap_minor"`
}

// =====================
// Treasury registry
// =====================
func (q *Queries) UpsertTreasuryWallet(ctx context.Context, arg UpsertTreasuryWalletParams) (TreasuryWallet, error) {
	row := q.db.QueryRow(ctx, upsertTreasuryWallet,
		arg.Role,
		arg.Chain,
		arg.Address,
		arg.Locator,
		arg.FloatCapMinor,
	)
	var i TreasuryWallet
	err := row.Scan(
		&i.ID,
		&i.Role,
		&i.Chain,
		&i.Address,
		&i.Locator,
		&i.FloatCapMinor,
		&i.CreatedAt,
	)
	return i, err
}
